<?php
declare(strict_types=1);
$id='CHAR(36) CHARACTER SET ascii COLLATE ascii_bin';
$e=' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci';
$sql=[
"CREATE TABLE support_departments(id $id PRIMARY KEY,name VARCHAR(191) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,allow_reopen BOOLEAN NOT NULL DEFAULT FALSE,allow_hold BOOLEAN NOT NULL DEFAULT FALSE,version INT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6))$e",
"CREATE TABLE support_department_members(department_id $id NOT NULL,user_id $id NOT NULL,created_by $id NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),PRIMARY KEY(department_id,user_id),FOREIGN KEY(department_id) REFERENCES support_departments(id),FOREIGN KEY(user_id) REFERENCES identity_staff(user_id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES identity_users(id))$e",
"CREATE TABLE support_tickets(id $id PRIMARY KEY,number VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,customer_id $id NOT NULL,requester_id $id NOT NULL,department_id $id NOT NULL,subject_encrypted TEXT NOT NULL,requested_priority VARCHAR(16) NOT NULL CHECK(requested_priority IN ('LOW','NORMAL','HIGH','CRITICAL')),effective_priority VARCHAR(16) NOT NULL CHECK(effective_priority IN ('LOW','NORMAL','HIGH','CRITICAL')),channel VARCHAR(16) NOT NULL CHECK(channel='PANEL'),status VARCHAR(24) NOT NULL CHECK(status IN ('NEW','WAITING_STAFF','WAITING_CUSTOMER','ON_HOLD','RESOLVED','CLOSED')),version INT UNSIGNED NOT NULL DEFAULT 1,opened_by $id NOT NULL,session_id $id NOT NULL,provenance VARCHAR(16) NOT NULL CHECK(provenance='TEST_PANEL'),created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_support_tenant(id,customer_id),KEY ix_support_customer(customer_id,updated_at,id),KEY ix_support_department(department_id,status,updated_at,id),FOREIGN KEY(customer_id) REFERENCES identity_customers(id),FOREIGN KEY(requester_id) REFERENCES identity_users(id),FOREIGN KEY(department_id) REFERENCES support_departments(id),FOREIGN KEY(opened_by) REFERENCES identity_users(id),FOREIGN KEY(session_id) REFERENCES identity_sessions(id))$e",
"CREATE TABLE support_messages(id $id PRIMARY KEY,ticket_id $id NOT NULL,customer_id $id NOT NULL,type VARCHAR(24) NOT NULL CHECK(type IN ('customer_reply','staff_reply','internal_note')),customer_visible BOOLEAN NOT NULL,CHECK((type='internal_note' AND customer_visible=FALSE) OR (type IN ('customer_reply','staff_reply') AND customer_visible=TRUE)),body_encrypted LONGTEXT NOT NULL,author_id $id NOT NULL,session_id $id NOT NULL,identity_version INT UNSIGNED NOT NULL,source VARCHAR(16) NOT NULL CHECK(source='TEST_PANEL'),created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),KEY ix_support_messages(ticket_id,created_at,id),FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(author_id) REFERENCES identity_users(id),FOREIGN KEY(session_id) REFERENCES identity_sessions(id))$e",
"CREATE TABLE support_ticket_links(ticket_id $id NOT NULL,customer_id $id NOT NULL,service_id $id NOT NULL,created_by $id NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),PRIMARY KEY(ticket_id,service_id),FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(service_id) REFERENCES svc_services(id),FOREIGN KEY(created_by) REFERENCES identity_users(id))$e",
"CREATE TABLE support_events(id $id PRIMARY KEY,ticket_id $id NULL,customer_id $id NULL,subject_id $id NOT NULL,kind VARCHAR(32) NOT NULL,actor_id $id NOT NULL,session_id $id NOT NULL,identity_version INT UNSIGNED NOT NULL,ticket_version INT UNSIGNED NULL,from_state VARCHAR(24) NULL,to_state VARCHAR(24) NULL,from_department $id NULL,to_department $id NULL,trace_id $id NOT NULL,provenance VARCHAR(16) NOT NULL CHECK(provenance='TEST_PANEL'),created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(actor_id) REFERENCES identity_users(id),FOREIGN KEY(session_id) REFERENCES identity_sessions(id),KEY ix_support_events(ticket_id,created_at,id))$e",
];
foreach(['support.ticket.view','support.ticket.reply','support.ticket.manage','support.ticket.internal_note'] as $p){$sql[]="INSERT INTO identity_permissions(code) VALUES ('$p')";$sql[]="INSERT INTO identity_role_permissions(role_id,permission) SELECT id,'$p' FROM identity_roles WHERE name IN ('Super Admin','Destek')";}
// No memberships or grants are auto-created: staff roles alone confer no ticket access.
foreach(['Teknik Destek','Satış','Muhasebe'] as $name){$uuid=\Hostider\Core\Id::uuid();$sql[]="INSERT INTO support_departments(id,name) VALUES ('$uuid','$name')";}
foreach(['support_messages','support_events','support_ticket_links'] as $table){foreach(['UPDATE','DELETE'] as $verb){$suffix=strtolower($verb);$sql[]="CREATE TRIGGER {$table}_no_{$suffix} BEFORE $verb ON $table FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable support record'";}}
$sql[]="CREATE TRIGGER support_tickets_identity BEFORE UPDATE ON support_tickets FOR EACH ROW BEGIN IF NOT(OLD.id<=>NEW.id) OR NOT(OLD.number<=>NEW.number) OR NOT(OLD.customer_id<=>NEW.customer_id) OR NOT(OLD.requester_id<=>NEW.requester_id) OR NOT(OLD.opened_by<=>NEW.opened_by) OR NOT(OLD.session_id<=>NEW.session_id) OR NOT(OLD.provenance<=>NEW.provenance) OR NOT(OLD.channel<=>NEW.channel) OR NOT(OLD.created_at<=>NEW.created_at) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable ticket ownership'; END IF; END";
return $sql;
